check("gateFromLatestRestore('share-portable'" in js and "gateFromLatestRestore('share-review-copy'" in js,'portable share actions gated')
check("gateFromLatestRestore('institutional-promotion'" in js,'institutional promotion gated')
check("kind:'cloud-revision'" in js and manifest['safe_actions']['sync_revision_preconditions_preserved'],'cloud revision review and sync preconditions preserved')
check('function recordSafeAction' in js and 'MAX_SAFE_ACTION_HISTORY = 120' in js,'browser-local gate decision ledger')
check('SCWorkspaceProjectDiff' in diff and 'compareProjects' in diff and "'/change-review-contract'" in php,'v0.24 deterministic Change Review retained')
